namespace ghidra.app.plugin.core.decompile.actions;






using docking;
using docking.action;
using docking.action;
using generic.theme;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.util;

public class CloneDecompilerAction : AbstractDecompilerAction {

	public CloneDecompilerAction() : base("Decompile Clone")
    {
		Icon image = new GIcon("icon.decompiler.action.provider.clone");
		setToolBarData(new ToolBarData(image, "ZZZ"));
		setDescription("Create a snapshot (disconnected) copy of this Decompiler window ");
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ToolBarSnapshot"));
		setKeyBindingData(new KeyBindingData(KeyEvent.VK_T,
			DockingUtils.CONTROL_KEY_MODIFIER_MASK | InputEvent.SHIFT_DOWN_MASK));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		return context.getFunction() != null;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		context.getComponentProvider().cloneWindow();
	}
}
